import React, { useState, useRef, useCallback, useEffect } from 'react';
import Webcam from 'react-webcam';
import { attendanceAPI } from './api_service';
import {
  CheckCircle,
  XCircle,
  RefreshCw,
  UserCheck,
  Fingerprint,
  Volume2,
  VolumeX,
  Square,
  Clock
} from 'lucide-react';

const CameraRecognition = () => {
  const webcamRef = useRef(null);
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);
  const [error, setError] = useState(null);
  const [autoMode, setAutoMode] = useState(false);
  const [soundEnabled, setSoundEnabled] = useState(true);

  // --- HELPER: Couleur de confiance ---
  const getConfidenceColor = (conf) => {
    const value = conf * 100;
    if (value > 80) return "#10B981"; 
    if (value > 60) return "#F59E0B"; 
    return "#EF4444"; 
  };

  const playSound = (type) => {
    if (!soundEnabled) return;
    const audio = new Audio(type === 'success' ? '/sounds/success.mp3' : '/sounds/error.mp3');
    audio.play().catch(() => console.error("Audio failed"));
  };

  const handleCapture = useCallback(async () => {
    if (!webcamRef.current) return;
    setLoading(true);
    setError(null);

    try {
      const imageSrc = webcamRef.current.getScreenshot();
      if (!imageSrc) throw new Error("Screenshot failed");

      const response = await attendanceAPI.recognize(imageSrc);
      const data = response?.data;

      if (!data || !(data.success || data.student)) {
        throw new Error(data?.error || "Recognition failed");
      }

      setResult({
        name: data.student || "Unknown",
        email: data.email || "N/A",
        confidence: data.confidence || 0,
        attendanceId: data.attendance_id || "N/A",
        time: new Date().toLocaleTimeString() // Ajout du timestamp
      });

      playSound('success');
    } catch (err) {
      setError(err?.response?.data?.error || err.message || "Recognition error");
      setResult(null);
      playSound('error');
    } finally {
      setLoading(false);
    }
  }, [soundEnabled]);

  useEffect(() => {
    let interval;
    if (autoMode) {
      interval = setInterval(() => {
        if (!loading) handleCapture();
      }, 5000);
    }
    return () => clearInterval(interval);
  }, [autoMode, loading, handleCapture]);

  return (
    <div style={styles.container}>
      {/* Injection de l'animation CSS pour le spinner */}
      <style>
        {`
          @keyframes spin {
            from { transform: rotate(0deg); }
            to { transform: rotate(360deg); }
          }
          .spin-icon {
            animation: spin 1s linear infinite;
          }
        `}
      </style>

      {/* HEADER */}
      <div style={styles.header}>
        <h1 style={styles.title}><UserCheck /> Face Recognition</h1>
        <button
          onClick={() => setSoundEnabled(!soundEnabled)}
          style={styles.iconBtn}
          aria-label="Toggle sound"
        >
          {soundEnabled ? <Volume2 /> : <VolumeX />}
        </button>
      </div>

      {/* CAMERA */}
      <div style={styles.cameraBox}>
        <Webcam
          ref={webcamRef}
          audio={false}
          screenshotFormat="image/jpeg"
          videoConstraints={{ width: 1280, height: 720, facingMode: "user" }}
          style={styles.webcam}
        />
        {loading && (
          <div style={styles.loadingOverlay}>
            <RefreshCw size={50} className="spin-icon" />
          </div>
        )}
      </div>

      {/* ACTIONS */}
      <div style={styles.actions}>
        <button
          onClick={handleCapture}
          disabled={loading || autoMode}
          style={{ ...styles.btn, background: (loading || autoMode) ? "#94A3B8" : "#4F46E5" }}
        >
          <Fingerprint size={20} /> {loading ? "Scanning..." : "Manual Scan"}
        </button>

        <button
          onClick={() => setAutoMode(!autoMode)}
          style={{ 
            ...styles.btn, 
            background: autoMode ? "#EF4444" : "#E2E8F0",
            color: autoMode ? "white" : "#1E293B"
          }}
        >
          {autoMode ? <><Square size={18} /> STOP AUTO</> : <><RefreshCw size={18} /> AUTO SCAN</>}
        </button>
      </div>

      {/* Feedback mode auto */}
      {autoMode && (
        <p style={styles.autoStatus}>
          <span className="spin-icon" style={{ display: 'inline-block' }}>⚙️</span> 
          Scan automatique en cours (toutes les 5s)...
        </p>
      )}

      {/* RESULT CARD */}
      <div style={styles.resultArea}>
        {result && (
          <div style={styles.card}>
            <div style={styles.cardHeader}>
              <CheckCircle color="#10B981" size={24} />
              <span style={{ fontWeight: 'bold' }}>Étudiant Identifié</span>
            </div>
            <div style={styles.cardBody}>
              <h3 style={{ margin: 0 }}>{result.name}</h3>
              <p style={{ color: '#64748B', margin: 0 }}>{result.email}</p>

              <div style={styles.infoGrid}>
                <div style={styles.infoItem}>
                  <Clock size={14} /> {result.time}
                </div>
                <div style={{ ...styles.infoItem, color: getConfidenceColor(result.confidence) }}>
                  <b>{(result.confidence * 100).toFixed(1)}% confidence</b>
                </div>
              </div>
              <div style={styles.idBadge}>ID: {result.attendanceId}</div>
            </div>
          </div>
        )}

        {error && (
          <div style={{ ...styles.card, borderLeft: "4px solid #EF4444" }}>
            <div style={styles.cardHeader}>
              <XCircle color="#EF4444" size={24} />
              <span style={{ fontWeight: 'bold', color: "#EF4444" }}>Échec</span>
            </div>
            <p style={{ margin: "8px 0 0 0" }}>{error}</p>
          </div>
        )}
      </div>
    </div>
  );
};

const styles = {
  container: { padding: 20, maxWidth: 600, margin: "auto", fontFamily: 'system-ui, sans-serif' },
  header: { display: "flex", justifyContent: "space-between", marginBottom: 20 },
  title: { display: "flex", gap: 10, alignItems: "center", fontSize: '1.4rem', color: '#1E293B' },
  iconBtn: { background: "transparent", border: "none", cursor: "pointer", color: '#64748B' },
  cameraBox: { position: "relative", borderRadius: 16, overflow: "hidden", boxShadow: "0 10px 15px -3px rgba(0,0,0,0.1)" },
  webcam: { width: "100%", display: "block" },
  loadingOverlay: { position: "absolute", inset: 0, background: "rgba(0,0,0,0.5)", display: "grid", placeItems: "center", color: "white" },
  actions: { display: "flex", gap: 12, marginTop: 20 },
  autoStatus: { textAlign: "center", color: "#6366F1", fontSize: "0.85rem", marginTop: 10, fontWeight: "500" },
  btn: { flex: 1, padding: '12px', borderRadius: 10, border: "none", cursor: "pointer", fontWeight: "600", display: "flex", gap: 8, justifyContent: "center", alignItems: "center", transition: "0.2s" },
  resultArea: { marginTop: 20, minHeight: 120 },
  card: { background: "white", padding: 20, borderRadius: 12, boxShadow: "0 4px 6px -1px rgba(0,0,0,0.1)", border: "1px solid #E2E8F0" },
  cardHeader: { display: "flex", alignItems: "center", gap: 10, marginBottom: 12 },
  cardBody: { display: "flex", flexDirection: "column", gap: 6 },
  infoGrid: { display: "flex", gap: 20, marginTop: 8, fontSize: "0.9rem", alignItems: "center" },
  infoItem: { display: "flex", alignItems: "center", gap: 5, color: "#475569" },
  idBadge: { marginTop: 8, padding: "4px 8px", background: "#F1F5F9", borderRadius: 6, fontSize: "0.75rem", color: "#64748B", alignSelf: "flex-start" }
};

export default CameraRecognition;
